// Unit tests of stats.js against values computed with scipy (stats.test-data.js, generated by
// tools/stats_fixtures.py) and of compare.js on a small synthetic design. Run them on js/stats.test.html,
// or from the console of the app: (await import("./js/stats.test.js")).runTests()
import { anova, betaInc, describe, fSf, holm, inhibition, stars, tCdf, tQuantile, welch } from "./stats.js";
import { FIXTURES } from "./stats.test-data.js";
import { buildComparison } from "./compare.js";
import { polygonArea } from "./geometry.js";

export function runTests() {
  const results = [];
  // Relative tolerance for statistics, absolute floor for values near 0.
  const close = (name, got, want, rel = 1e-9, abs = 1e-12) => {
    const ok = got != null && Number.isFinite(got) && Math.abs(got - want) <= Math.max(abs, rel * Math.abs(want));
    results.push({ name, ok, got, want });
  };
  const is = (name, got, want) => results.push({ name, ok: got === want, got, want });
  const S = FIXTURES.samples;

  for (const [k, d] of Object.entries(FIXTURES.describe)) {
    const r = describe(S[k]);
    is(`describe ${k} n`, r.n, d.n);
    close(`describe ${k} mean`, r.mean, d.mean, 1e-12);
    close(`describe ${k} SD`, r.sd, d.sd, 1e-12);
    close(`describe ${k} SEM`, r.sem, d.sem, 1e-12);
    close(`describe ${k} 95% CI low`, r.ciLow, d.ciLow, 1e-9);
    close(`describe ${k} 95% CI high`, r.ciHigh, d.ciHigh, 1e-9);
  }
  for (const w of FIXTURES.welch) {
    const r = welch(S[w.a], S[w.b]);
    close(`Welch ${w.a} vs ${w.b} t`, r.t, w.t, 1e-10);
    close(`Welch ${w.a} vs ${w.b} df`, r.df, w.df, 1e-10);
    close(`Welch ${w.a} vs ${w.b} p`, r.p, w.p, 1e-7);
  }
  for (const a of FIXTURES.anova) {
    const r = anova(a.groups.map((g) => S[g]));
    const name = a.groups.join("+");
    close(`ANOVA ${name} F`, r.F, a.F, 1e-10);
    is(`ANOVA ${name} df`, `${r.df1},${r.df2}`, `${a.df1},${a.df2}`);
    close(`ANOVA ${name} p`, r.p, a.p, 1e-7);
  }
  for (const c of FIXTURES.tCdf) close(`t CDF(${c.t}; df ${c.df})`, tCdf(c.t, c.df), c.p, 1e-9);
  for (const c of FIXTURES.tPpf) close(`t quantile(${c.p}; df ${c.df})`, tQuantile(c.p, c.df), c.t, 1e-9);
  for (const c of FIXTURES.fSf) close(`F upper tail(${c.f}; ${c.d1}, ${c.d2})`, fSf(c.f, c.d1, c.d2), c.p, 1e-8);
  for (const c of FIXTURES.betaInc) close(`I_${c.x}(${c.a}, ${c.b})`, betaInc(c.x, c.a, c.b), c.v, 1e-10);
  for (const c of FIXTURES.holm) {
    const got = holm(c.p);
    c.adj.forEach((v, i) => close(`Holm [${c.p}] #${i + 1}`, got[i], v, 1e-12));
  }
  is("Holm keeps nulls", JSON.stringify(holm([0.01, null, 0.02])), JSON.stringify([0.02, null, 0.02]));
  is("Welch n<2 -> null", welch([1], [1, 2, 3]), null);
  is("Welch no variance -> null", welch([2, 2], [2, 2]), null);
  is("stars", [0.00005, 0.0005, 0.005, 0.03, 0.2, null].map(stars).join(" "), "**** *** ** * ns ");
  const inh = inhibition(30, 3, 40, 2);
  close("inhibition %", inh.pct, 25);
  close("inhibition SD (delta method)", inh.sd, 100 * 0.75 * Math.sqrt(0.01 + 0.0025));
  close("inhibition SD at mT = 0", inhibition(0, 1, 40, 2).sd, 2.5);

  // compare.js: control + 2 treatments × 3 biological replicates, two technical replicates each for treatment A.
  const plate = { cx: 500, cy: 500, r: 400 }; // 90 mm plate -> 0.1125 mm/px
  const k = 90 / 800;
  const circ = (dMm) => { const r = dMm / 2 / k; return Array.from({ length: 360 }, (_, i) => [500 + r * Math.cos(i * Math.PI / 180), 500 + r * Math.sin(i * Math.PI / 180)]); };
  let id = 0;
  const img = (condition, role, bioRep, dMm, techRep = null, klass = "incomplete") => ({
    id: `i${++id}`, name: `${condition}-${bioRep}${techRep || ""}.jpg`, scale: 1, notes: "",
    meta: { strain: "PAO1", condition, role, bioRep, techRep },
    result: { klass, plate, contour: klass === "complete" ? [] : circ(dMm), areaPx: klass === "complete" ? Math.PI * 400 * 400 : polygonArea(circ(dMm)) } });
  const ctl = [40, 42, 44], A = [[30, 32], [28, 30], [33, 35]], B = [41, 39, 90];
  const images = [
    ...ctl.map((d, i) => img("DMSO", "vehicle", `${i + 1}`, d)),
    ...A.flatMap((ds, i) => ds.map((d, j) => img("A", null, `${i + 1}`, d, `${j + 1}`))),
    ...B.map((d, i) => img("B", "sample", `${i + 1}`, d, null, d === 90 ? "complete" : "incomplete")),
  ];
  const exp = { id: "e", name: "test", meta: { plateDiameterMm: 90 }, compare: { measure: "eqDiameterMm" } };
  const cmp = buildComparison(images, exp, { plateDiameterMm: 90, manualPxPerMm: null });
  const fam = cmp.families[0];
  is("compare: one family", cmp.families.length, 1);
  is("compare: control is the vehicle", fam.control?.condition, "DMSO");
  const rA = fam.rows.find((r) => r.condition === "A"), rB = fam.rows.find((r) => r.condition === "B");
  is("compare: A has 3 biological replicates from 6 plates", `${rA.n}/${rA.nPlates}`, "3/6");
  const aMeans = A.map((ds) => (ds[0] + ds[1]) / 2);
  const wantA = describe(aMeans), wantC = describe(ctl);
  close("compare: A mean of replicate means", rA.mean, wantA.mean, 1e-3);
  close("compare: A SD", rA.sd, wantA.sd, 1e-2);
  close("compare: A % inhibition", rA.inhibitionPct, (1 - wantA.mean / wantC.mean) * 100, 1e-3);
  close("compare: A Welch p", rA.p, welch(aMeans, ctl).p, 1e-2);
  close("compare: Holm over A and B", rA.pAdj, holm([welch(aMeans, ctl).p, welch(B, ctl).p])[0], 1e-2);
  is("compare: complete plate counted", rB.nComplete, 1);
  close("compare: complete plate = plate diameter", rB.values[2], 90, 1e-9);
  close("compare: per-image inhibition", cmp.perImage.get(images[3].id).inhibitionPct, (1 - 30 / wantC.mean) * 100, 1e-3);
  is("compare: ANOVA computed", fam.anova != null, true);
  const noCtl = buildComparison(images.filter((i) => i.meta.role !== "vehicle"), exp, { plateDiameterMm: 90 });
  is("compare: missing control warned", noCtl.warnings.some((w) => w.code === "noControl"), true);

  const failed = results.filter((r) => !r.ok);
  console.table(results);
  console.log(failed.length ? `stats.js: ${failed.length} of ${results.length} tests FAILED` : `stats.js: all ${results.length} tests passed`);
  return { passed: results.length - failed.length, failed: failed.length, results };
}
